            return files
        except Exception as e:
            logger.error(f"Error listing files in bucket {self.bucket}: {str(e)}", exc_info=True)
            raise ValueError(f"Failed to list files: {str(e)}")

    def upload_file(self, file_obj: BinaryIO, filename: str) -> None:
