                if not secret_key:
                    return jsonify({'error': 'Secret Access Key is required'}), 400
                if not bucket:
                    return jsonify({'error': 'Bucket name is required'}), 400
                if not re.match(r'^[a-zA-Z0-9.\-_]{3,63}$', bucket):
                    return jsonify({'error': 'Invalid bucket name format'}), 400

